<template>
  <section>
    <div class="row" style="align-items:flex-start"><div><div class="eyebrow">WORKSPACE OVERVIEW</div><h1>Overview</h1><p class="muted">A live view of projects, fleet nodes, recent API events, and reported telemetry.</p></div><button class="ghost" style="margin-left:auto" :disabled="loading || telemetryLoading" @click="load">{{ loading || telemetryLoading ? 'Refreshing…' : 'Refresh' }}</button></div>
    <div v-if="loading" class="empty" aria-live="polite">Loading workspace overview…</div>
    <div v-else-if="error" class="empty" role="alert">{{ error }} <button class="ghost" @click="load">Retry</button></div>
    <template v-else>
      <div class="stats-grid"><router-link to="/projects" class="card stat-card"><span class="stat-label">Projects</span><strong>{{ projects.length }}</strong><small>Projects returned by the API</small></router-link><router-link to="/nodes" class="card stat-card"><span class="stat-label">Fleet nodes</span><strong>{{ nodes.length }}</strong><small>Registered nodes returned by the API</small></router-link></div>
      <div class="section-head"><div><h2>Recent activity</h2><p class="muted">Latest events returned by the API.</p></div></div>
      <div class="card activity-card"><div v-if="events.length" class="activity-list"><div v-for="event in events" :key="event.id" class="activity-row"><span class="activity-indicator"></span><div class="activity-body"><strong>{{ event.type }}</strong><small>{{ relatedIds(event) || 'Event' }}</small></div><span class="activity-time">{{ formatTime(event.occurred_at) }}</span></div></div><div v-else class="empty activity-empty">No recent events.</div></div>
      <div class="section-head"><div><h2>Latest telemetry</h2><p class="muted">Agent/runtime logs and host/Firecracker-process metrics; not application stdout/stderr or distributed traces.</p></div><router-link to="/observability" class="subtle-link">Open Observability →</router-link></div>
      <div v-if="telemetryLoading" class="card telemetry-state" aria-live="polite">Loading telemetry summaries…</div>
      <div v-else-if="telemetryError" class="card telemetry-state error" role="alert">{{ telemetryError }} <button class="ghost" @click="loadTelemetry">Retry telemetry</button></div>
      <div v-else class="telemetry-grid"><article class="card"><h3>Latest log record</h3><template v-if="latestLog"><strong>{{ latestLog.level }}</strong><p>{{ latestLog.message }}</p><small>{{ formatTime(latestLog.reported_at) }} · node {{ latestLog.node_id }}<span v-if="latestLog.instance_id"> · instance {{ latestLog.instance_id }}</span></small></template><p v-else class="empty">No log records reported.</p></article><article class="card"><h3>Latest metric record</h3><template v-if="latestMetric"><strong>{{ latestMetric.name }}: {{ latestMetric.value }} {{ latestMetric.unit }}</strong><small>{{ formatTime(latestMetric.reported_at) }} · node {{ latestMetric.node_id }}<span v-if="latestMetric.instance_id"> · instance {{ latestMetric.instance_id }}</span></small></template><p v-else class="empty">No metric records reported.</p></article></div>
    </template>
  </section>
</template>
<script setup>
import { computed, ref, onMounted } from 'vue'
import { get, listAll } from '../lib/api.js'
const loading = ref(true), error = ref(''), projects = ref([]), nodes = ref([]), events = ref([])
const telemetryLoading = ref(true), telemetryError = ref(''), logs = ref([]), metrics = ref([])
const latestLog = computed(() => [...logs.value].sort((a,b) => Date.parse(b.reported_at)-Date.parse(a.reported_at))[0])
const latestMetric = computed(() => [...metrics.value].sort((a,b) => Date.parse(b.reported_at)-Date.parse(a.reported_at))[0])
function relatedIds(event) { return ['project_id','service_id','release_id','instance_id','fleet_node_id','operation_id','command_id'].filter(key => event[key]).map(key => `${key.replace('_id','')}: ${event[key]}`).join(' · ') }
function formatTime(value) { if (!value) return '—'; const time = Date.parse(value); return Number.isNaN(time) ? '—' : new Date(time).toLocaleString() }
async function loadTelemetry() { telemetryLoading.value=true; telemetryError.value=''; const to=new Date(), from=new Date(to.getTime()-24*3600000), params=new URLSearchParams({from:from.toISOString(),to:to.toISOString(),page_size:'100'}); try { const [l,m]=await Promise.all([get(`/logs?${params}`),get(`/metrics?${params}`)]); if(!Array.isArray(l?.items)||!Array.isArray(m?.items)) throw new Error('The API returned an invalid telemetry page.'); logs.value=l.items; metrics.value=m.items } catch(e) { telemetryError.value=`Could not load telemetry — ${e.message || 'Unknown API error'}`; logs.value=[]; metrics.value=[] } finally { telemetryLoading.value=false } }
async function load() { loading.value=true; error.value=''; try { const results = await Promise.all([listAll('/projects'), listAll('/fleet/nodes'), get('/events?page_size=10')]); projects.value=results[0]; nodes.value=results[1]; events.value=Array.isArray(results[2]?.items)?results[2].items:[] } catch (err) { error.value=`Failed to load workspace overview — ${err.message || 'Unknown API error'}` } finally { loading.value=false } loadTelemetry() }
onMounted(load)
</script>
<style scoped>
.eyebrow{font-size:10px;letter-spacing:.12em;color:var(--ink2);font-weight:700;margin-bottom:8px}.stats-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:14px}.stat-card{display:flex;flex-direction:column;color:inherit;padding:16px 18px}.stat-label{color:var(--ink2);font-size:11px;font-weight:600}.stat-card strong{font-size:26px;margin:6px 0 3px}.stat-card small{font-size:10px;color:var(--ink3)}.section-head{display:flex;justify-content:space-between;align-items:end;margin:24px 2px 9px}.section-head h2{margin:0 0 3px;font-size:14px}.section-head p{font-size:11px}.activity-card{padding:4px 16px}.activity-row{display:flex;align-items:center;gap:11px;padding:12px 0;border-bottom:1px solid var(--soft)}.activity-row:last-child{border:0}.activity-indicator{width:8px;height:8px;border-radius:50%;background:#77869a;flex:none}.activity-body{min-width:0;flex:1}.activity-body strong,.activity-body small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.activity-body strong{font-size:11px}.activity-body small,.activity-time{font-size:10px;color:var(--ink3);margin-top:2px}.activity-time{white-space:nowrap}.activity-empty{border:0;padding:22px}.telemetry-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.telemetry-grid .card,.telemetry-state{padding:14px}.telemetry-grid h3{font-size:11px;margin:0 0 9px}.telemetry-grid strong,.telemetry-grid small{display:block;font-size:10px;overflow-wrap:anywhere}.telemetry-grid small{color:var(--ink3);margin-top:7px}.telemetry-grid p{font-size:11px;overflow-wrap:anywhere}.error{color:#ff9ba5}@media(max-width:650px){.stats-grid,.telemetry-grid{grid-template-columns:1fr}}
</style>
